{
  "schema_version": 1,
  "name": "CHOIS official OMOMO text-motion evaluator",
  "upstream_url": "https://github.com/lijiaman/chois_release.git",
  "upstream_commit": "8ec585aa0200fd2a890ffb12897bcf69ae719463",
  "files": {
    "t2m_eval/final_evaluations.py": "a5e7f64f9924238361d265749be80ff98cbf0e3f544102b6c8be1bf79db49ca3",
    "evaluation_metrics.py": "e3998e061fc697639e76ebb1a0a60bb36b41496d27804ff20f583d5973f30330"
  },
  "input_contract": {
    "format": "one NPZ per sequence",
    "required_keys": {
      "seq_name": "scalar string matching the official OMOMO annotation id",
      "global_jpos": "float array [T,24,3], in the official evaluator coordinate convention"
    }
  },
  "reported_metrics": ["FID", "R-Precision@1", "R-Precision@2", "R-Precision@3"],
  "required_external_assets": [
    "official CHOIS OMOMO text-motion feature checkpoint",
    "official GloVe vocabulary files",
    "official processed OMOMO text annotations and t2m_mean_std_jpos.p"
  ],
  "release_audit": {
    "status": "adapter-regression-passed",
    "notes": "The pinned release uses author-local absolute paths and imports options/train_options.py, which is absent from the release. tools/run_chois_evaluator.py supplies the parser from the separately pinned EricGuo5513/text-to-motion dependency and passes every data path explicitly, without editing the CHOIS checkout. The official supplied CHOIS result set has 482 sequences while its GT set has 480, so the adapter intentionally preserves the released evaluator's independent-set FID semantics. The 2026-07-12 supplied-result GPU regression produced FID=0.6881585766 and R-Precision@1/2/3=0.1520833333/0.2979166667/0.425; InfBaGel metrics remain pending a clean-worktree reportable run."
  }
}

